/**
 * THE PARITY PROOF for check runs on members-only branches (`docs/security/private-repos.md`
 * §19.8): every `members_check__` vector in `forge-contracts/vectors/` (generated by
 * `tools/private-repos-vectors/members_checks.py`), run against `./members-check`. forge-core
 * `private::members_check` runs the same files.
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'

import { bytesToHex, hexToBytes, sha256 } from './bytes'
import { CheckKeys, CheckLogError, base32, isOpaqueName } from './members-check'

interface Vector {
  readonly name: string
  readonly case: string
  readonly input: Record<string, string>
  readonly expected: Record<string, unknown>
}

const VECTORS_DIR = resolve(process.cwd(), '..', 'forge-contracts', 'vectors')
const FILES = readdirSync(VECTORS_DIR)
  .filter((f) => f.startsWith('members_check__') && f.endsWith('.json'))
  .sort()

async function run(v: Vector): Promise<Record<string, unknown>> {
  const at = (k: string): string => {
    const x = v.input[k]
    if (x === undefined) throw new Error(`${v.name}: no input ${k}`)
    return x
  }
  const hex = (k: string) => hexToBytes(at(k))
  const keys = await CheckKeys.of(hex('salt'))
  switch (at('op')) {
    case 'name':
      return { nameKey: bytesToHex(keys.nameKeyForVectors()), opaque: await keys.opaqueName(at('name')) }
    case 'seal': {
      const sealed = await keys.sealLog(hex('blind'), at('name'), hex('head'), hex('log'), hex('nonce'))
      return { opaque: await keys.opaqueName(at('name')), sealed: bytesToHex(sealed), sha256: bytesToHex(await sha256(sealed)) }
    }
    case 'open':
      try {
        const l = await keys.openLog(hex('blind'), at('opaque'), hex('sealed'))
        return { name: l.name, head: l.head, log: bytesToHex(l.log) }
      } catch (e) {
        if (!(e instanceof CheckLogError)) throw e
        return e.kind === 'unknownVersion' ? { error: 'unknownVersion', version: e.version } : { error: 'malformed' }
      }
    default:
      throw new Error(`unknown op ${at('op')}`)
  }
}

describe('members_check vectors', () => {
  it('loads the corpus', () => {
    expect(FILES.length).toBeGreaterThanOrEqual(24)
  })
  for (const f of FILES) {
    const v = JSON.parse(readFileSync(resolve(VECTORS_DIR, f), 'utf8')) as Vector
    it(v.name, async () => {
      expect(await run(v)).toEqual(v.expected)
    })
  }
  it('base32 is RFC 4648, lower case, unpadded', () => {
    const enc = (s: string) => base32(new TextEncoder().encode(s))
    expect(['', 'f', 'fo', 'foo', 'foob', 'fooba', 'foobar'].map(enc)).toEqual(['', 'my', 'mzxq', 'mzxw6', 'mzxw6yq', 'mzxw6ytb', 'mzxw6ytboi'])
    expect(isOpaqueName('mzxw6ytboimzxw6y')).toBe(true)
    expect(isOpaqueName('ci / build')).toBe(false)
  })
})
